int maksSumaOknaK(int[] tab, int k) {
    int sumaOkna = 0;
    for (int i = 0; i < k; i++) sumaOkna += tab[i]; // pierwsze okno - liczone normalnie

    int najlepsza = sumaOkna;
    for (int prawy = k; prawy < tab.length; prawy++) {
        sumaOkna += tab[prawy] - tab[prawy - k]; // dodaj nowy, odejmij ten co wypadl
        najlepsza = Math.max(najlepsza, sumaOkna);
    }
    return najlepsza;
}

int najdluzszyBezPowtorzen(String s) {
    Set<Character> wOknie = new HashSet<>();
    int lewy = 0, najlepsza = 0;
    for (int prawy = 0; prawy < s.length(); prawy++) {
        char znak = s.charAt(prawy);
        while (wOknie.contains(znak)) { // okno ma duplikat - kurcz od lewej
            wOknie.remove(s.charAt(lewy));
            lewy++;
        }
        wOknie.add(znak);
        najlepsza = Math.max(najlepsza, prawy - lewy + 1);
    }
    return najlepsza;
}

int maksSumaOknaK_WOLNO(int[] tab, int k) {
    int najlepsza = Integer.MIN_VALUE;
    for (int lewy = 0; lewy + k <= tab.length; lewy++) {
        int suma = 0;
        for (int i = lewy; i < lewy + k; i++) suma += tab[i]; // przeliczanie OD ZERA za kazdym razem!
        najlepsza = Math.max(najlepsza, suma);
    }
    return najlepsza;
} // O(n*k) zamiast O(n) - traci caly sens sliding window

