int najkrotsze(int[] tab, int cel) {
    int lewy = 0, suma = 0, best = Integer.MAX_VALUE;
    for (int prawy = 0; prawy < tab.length; prawy++) {
        suma += tab[prawy];
        while (suma >= cel) {
            best = Math.min(best, prawy - lewy + 1);
            suma -= tab[lewy++];
        }
    }
    return best == Integer.MAX_VALUE ? 0 : best;
}
